package io.quizforge.desktop.poc.sharedpractice;
import io.quizforge.core.practice.*;import io.quizforge.core.practice.draft.DraftCanvasDocument;import io.quizforge.core.question.content.TextContent;import io.quizforge.core.question.model.*;import io.quizforge.core.question.type.subjective.essay.*;import io.quizforge.desktop.ui.question.history.HistoryDraftAdapter;import io.quizforge.infrastructure.filesystem.qbank.QuestionBankV2Codec;import io.quizforge.infrastructure.persistence.SqliteDatabase;import io.quizforge.infrastructure.persistence.practice.*;import java.nio.file.Path;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;
class SharedEssayAdapterTest {
 @TempDir Path directory;
 QuestionBank bank(){var q=new Question("q_essay","ESSAY",List.of(),new TextContent("Write an essay. Literal {{braces}} are ordinary text."),new EssayPayload(null),new EssayAnswerSpec(new TextContent("Essay reference")),new ScoreSpec(java.math.BigDecimal.valueOf(5)),null,new TextContent("Frozen analysis"),List.of());return new QuestionBank("qb_essay_contract","Essay contract","2.0",List.of(),List.of(q),List.of());}
 @Test void formalTextIsSeparateFromCanvasAndUnscoredRetryKeepsFrozenAttempts(){var db=new SqliteDatabase(directory.resolve("practice.db"));var tx=new SqlitePracticeTransaction(db);var service=new PracticeSessionService(tx,Clock.systemUTC());var bank=bank();var revision=new QuestionBankV2Codec().contentId(bank);var adapter=new SharedPracticeAdapter(service,service.openOrCreateActiveSession(bank,revision));String parent=adapter.viewModel().question().sessionQuestionId();assertEquals("LONG_TEXT",adapter.viewModel().question().selectionMode());assertFalse(adapter.viewModelJson().contains("Essay reference"));assertFalse(adapter.viewModelJson().contains("Frozen analysis"));adapter.essayChanged("Draft essay\n中文");var reopened=new SharedPracticeAdapter(service,service.openOrCreateActiveSession(bank,revision));assertEquals(parent,reopened.viewModel().question().sessionQuestionId());assertEquals("Draft essay\n中文",((SharedPracticeViewModel.EssayPresentation)reopened.viewModel().question().presentation()).answer().text());var draft=DraftCanvasDocument.createEmpty();adapter.saveDraft(draft);var first=adapter.submit().question().result();assertEquals("UNSCORED",first.status());assertNull(first.score());assertEquals(5,first.maxScore());var snapshots=new SqliteAttemptDraftSnapshotRepository(db);var frozen=snapshots.find(first.attemptId()).orElseThrow();assertThrows(IllegalStateException.class,()->adapter.essayChanged("Forbidden"));adapter.retry();assertEquals("",((SharedPracticeViewModel.EssayPresentation)adapter.viewModel().question().presentation()).answer().text());assertEquals(DraftCanvasDocument.createEmpty(),adapter.loadDraft());adapter.essayChanged("Second essay");adapter.saveDraft(DraftCanvasDocument.createEmpty());var second=adapter.submit().question().result();assertEquals("UNSCORED",second.status());assertEquals("RETRY",second.attemptMode());assertEquals(frozen,snapshots.find(first.attemptId()).orElseThrow());new SqlitePracticeSessionRepository(db).archive(adapter.snapshot().session().id(),Instant.now());var history=new PracticeHistoryService(tx);var detail=history.loadArchivedSessionDetail(bank.assetId(),adapter.snapshot().session().id());var projection=new HistoryDraftAdapter(history,bank.assetId(),detail);var row=detail.questions().getFirst();var a=projection.load(row,row.attempts().getFirst());var b=projection.load(row,row.attempts().getLast());assertNotNull(a.card());assertEquals(first.attemptId(),a.card().question().result().attemptId());assertEquals(second.attemptId(),b.card().question().result().attemptId());assertEquals("Draft essay\n中文",((SharedPracticeViewModel.EssayPresentation)a.card().question().presentation()).answer().text());assertEquals("Second essay",((SharedPracticeViewModel.EssayPresentation)b.card().question().presentation()).answer().text());assertEquals("Essay reference",((SharedPracticeViewModel.EssayPresentation)a.card().question().presentation()).reference().text());assertEquals(draft,a.draft().document());assertEquals(frozen,snapshots.find(first.attemptId()).orElseThrow());}
}
